export const BODY_EXCLUDE_PATTERNS = [
  '**/*.test.ts',
  'tests/**/*.ts',
  // Both test roots are named explicitly, mirroring INCLUDE_PATTERNS above,
  // because `**/tests/**/*.ts` would be wrong here: globToRegExp compiles `**`
  // to `.*` with no path-boundary anchoring, so that pattern also matches
  // `src/contests/foo.ts`. An over-broad body exclusion is the one failure this
  // file cannot afford — it would hide real source from the reviewer.
  'extension/tests/**/*.ts',
];

const [pr, explicitBase] = positional;
if (!pr) {
  throw new Error('usage: npm run ai-review-replay -- <pr-number> [base-sha] [--head <sha>]');
}
return {
  pr,
  ...(explicitBase ? { explicitBase } : {}),
  ...(headOverride ? { headOverride } : {}),
};

const meta = JSON.parse(
  gh(['pr', 'view', pr, '--json', 'title,body,headRefOid,baseRefName']),
) as { title: string; body: string; headRefOid: string; baseRefName: string };

const head = headOverride ?? meta.headRefOid;

try {
  sh(['fetch', 'origin', `pull/${pr}/head`]);
} catch (err) {
  // With `--head` the pull ref is a best-effort first try; letting it
  // throw here would bury the by-sha attempt that is the whole point.
  if (!headOverride) throw err;
}
if (headOverride && !hasCommit(head)) sh(['fetch', 'origin', head]);

